window.RP_SESSION={"id":"S-98a6839767a0","messages":[{"id":"RP-II-0195862","time":"2026-09-17T13:28:00+09:00","room":"RP II","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"짐을 정리하던 중이었다. \n\n잡동사니를 치우고, 생긴 쓰레기는 버리고.\n\n나뒹굴던 룬석(실수로 제작에 실패함)따위를 한데 쓸어모아 재활용을 도모하기로 하고.\n\n하나 남은 마나 크리스탈은 먼지를 잘 털어 책장에 두었다.\n\n그러던 중, 직육면체의 나무상자가 눈에 들어왔다.","characters":["P-b3929f308454"]},{"id":"RP-II-0195863","time":"2026-09-17T13:28:00+09:00","room":"RP II","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...? \"","characters":["P-b3929f308454"]},{"id":"RP-II-0195864","time":"2026-09-17T13:29:00+09:00","room":"RP II","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그것을 열어보니, 들어있는 것은 과거 수집하고, 대회도 나갔었던 덱이었다.","characters":["P-b3929f308454"]},{"id":"RP-II-0195865","time":"2026-09-17T13:29:00+09:00","room":"RP II","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...오. 아직 쓸 수 있으려나. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0195866","time":"2026-09-17T13:30:00+09:00","room":"RP II","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"이내 상자를 챙겨 한동안 가지 않았던 '그 거리'로 향했다.","characters":["P-b3929f308454"]},{"id":"RP-II-0195867","time":"2026-09-17T13:32:00+09:00","room":"RP II","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그 거리에는 가판대가 있다.\n\n다양한 사람들이 종이딱지를 두어장씩 전시하고, 가격을 적어두는 곳이다.","characters":["P-b3929f308454"]},{"id":"RP-II-0195868","time":"2026-09-17T13:33:00+09:00","room":"RP II","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"이곳에서 종이딱지를 사기도, 팔기도 한다.\n\n그리고 그것으로 대결을 하지.\n\n주로 어린 아이들이 타겟층이지만, 이따금씩 어른들도 보이는 그런 곳이었다.","characters":["P-b3929f308454"]},{"id":"RP-II-0195869","time":"2026-09-17T13:33:00+09:00","room":"RP II","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-b3929f308454"]},{"id":"RP-II-0195870","time":"2026-09-17T13:34:00+09:00","room":"RP II","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...임마는 가격도 안 떨어짐까. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0195871","time":"2026-09-17T13:34:00+09:00","room":"RP II","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"이내 가판대를 뒤로하고, 지나가던 사람을 붙잡아 친선 대결을 두어판하고 돌아왔다.","characters":["P-b3929f308454"]},{"id":"RP-II-0195872","time":"2026-09-17T13:34:00+09:00","room":"RP II","name":"코블스톤","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b3929f308454"]},{"id":"RP-II-0195873","time":"2026-09-17T13:34:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
